cases.bad:
// exitFullscreenDocked → showPanelDocked ngay lập tức
showPanelDocked(); // bên trong: const h = f0.getBoundingClientRect().height;
// f0 vẫn còn display:flex, height:100% từ fullscreen → h = 48px (collapsed) → lock sai → layout break

cases.good:
// 1. Clear fullscreen class + inline styles trước
playerContainer.classList.remove('art-fullscreen');
['display','flex','height','aspect-ratio','box-sizing','min-width','min-height'].forEach(p => {
  f0.style.removeProperty(p); playerContainer.style.removeProperty(p);
});
// 2. Force reflow để browser tính lại natural size
void f0.offsetHeight;
// 3. mới measure — giờ là true natural height
showPanelDocked(); // const h = f0.getBoundingClientRect().height; // 507px ✓

// Clear container height first, force reflow, then measure
container.style.height = '';
void el.offsetHeight;
const naturalH = el.getBoundingClientRect().height; // true natural value
container.style.height = naturalH + 'px'; // lock definite value
